begin;
grant select,insert,update,delete on table public.physique_athletes,public.physique_training_plans,public.physique_training_days,public.physique_training_exercises,public.physique_training_attachments to authenticated;
create or replace function public.generate_public_quote_number() returns bigint language plpgsql security definer set search_path=public as $$ declare v_number bigint;v_attempt integer;begin perform pg_advisory_xact_lock(93742111);for v_attempt in 1..200 loop v_number:=floor(random()*9000000)::bigint+1000000;if not exists(select 1 from public.sales_quotes where quote_number=v_number) and not exists(select 1 from public.fitness_quotes where quote_number=v_number) then return v_number;end if;end loop;raise exception 'Não foi possível gerar um número público de orçamento único';end;$$;
alter table public.sales_quotes alter column quote_number drop identity if exists;alter table public.sales_quotes alter column quote_number set default public.generate_public_quote_number();alter table public.fitness_quotes alter column quote_number set default public.generate_public_quote_number();
do $$ declare r record;begin for r in select id from public.sales_quotes order by created_at,id loop update public.sales_quotes set quote_number=public.generate_public_quote_number() where id=r.id;end loop;for r in select id from public.fitness_quotes order by created_at,id loop update public.fitness_quotes set quote_number=public.generate_public_quote_number() where id=r.id;end loop;end;$$;
create table if not exists public.physique_athlete_import_sessions(id uuid primary key default gen_random_uuid(),athlete_id uuid not null references public.physique_athletes(id) on delete cascade,title text not null,status text not null default 'open' check(status in('open','completed','cancelled')),context jsonb not null default '{}'::jsonb,ai_summary text,created_by uuid default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.physique_athlete_import_files(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.physique_athlete_import_sessions(id) on delete cascade,athlete_id uuid not null references public.physique_athletes(id) on delete cascade,file_type text not null,file_name text not null,file_url text not null,mime_type text,file_size_bytes bigint,ai_payload jsonb not null default '{}'::jsonb,ai_summary text,created_at timestamptz not null default now());
create table if not exists public.physique_athlete_snapshots(id uuid primary key default gen_random_uuid(),athlete_id uuid not null references public.physique_athletes(id) on delete cascade,session_id uuid references public.physique_athlete_import_sessions(id) on delete set null,source_file_id uuid references public.physique_athlete_import_files(id) on delete set null,snapshot_type text not null,snapshot_date date not null default((now() at time zone 'America/Sao_Paulo')::date),payload jsonb not null default '{}'::jsonb,summary text,created_at timestamptz not null default now());
create index if not exists physique_athlete_import_sessions_athlete_idx on public.physique_athlete_import_sessions(athlete_id,created_at desc);create index if not exists physique_athlete_import_files_session_idx on public.physique_athlete_import_files(session_id,created_at);create index if not exists physique_athlete_snapshots_athlete_idx on public.physique_athlete_snapshots(athlete_id,snapshot_date desc,created_at desc);
alter table public.physique_athlete_import_sessions enable row level security;alter table public.physique_athlete_import_files enable row level security;alter table public.physique_athlete_snapshots enable row level security;
drop policy if exists physique_athlete_import_sessions_manage on public.physique_athlete_import_sessions;create policy physique_athlete_import_sessions_manage on public.physique_athlete_import_sessions for all to authenticated using(public.can_manage_physique()) with check(public.can_manage_physique());drop policy if exists physique_athlete_import_files_manage on public.physique_athlete_import_files;create policy physique_athlete_import_files_manage on public.physique_athlete_import_files for all to authenticated using(public.can_manage_physique()) with check(public.can_manage_physique());drop policy if exists physique_athlete_snapshots_manage on public.physique_athlete_snapshots;create policy physique_athlete_snapshots_manage on public.physique_athlete_snapshots for all to authenticated using(public.can_manage_physique()) with check(public.can_manage_physique());grant select,insert,update,delete on table public.physique_athlete_import_sessions,public.physique_athlete_import_files,public.physique_athlete_snapshots to authenticated;
commit;
